#include <iostream>
#include <vector>
#include <string>
using namespace std;

long long digitSum(long long n) {
    if (n == 0) {
        return 0;
    }
    return n % 10 + digitSum(n / 10);
}

int main() {
    long long n;
    cin >> n;

    cout << digitSum(n) << endl;

    return 0;
}

code.java:
import java.util.*;

public class Main {
    static long digitSum(long n) {
        if (n == 0) {
            return 0;
        }
        return n % 10 + digitSum(n / 10);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();

        System.out.println(digitSum(n));
    }
}
